#include<bits/stdc++.h>
#include<atcoder/dsu>

using namespace std;
using namespace atcoder;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> p(n);
    for (int i = 1; i < n; i++) {
        cin >> p[i];
        --p[i];
    }

    dsu uf(n);
    vector<int> r(n); // r[i] = i を代表元とする強連結成分内の最小頂点
    iota(r.begin(), r.end(), 0);
    auto get_min = [&](int i) { return r[uf.leader(i)]; }; // i を含む強連結成分内の最小頂点
    int q;
    cin >> q;
    while (q--) {
        int t;
        cin >> t;
        if (t == 1) {
            int u, v;
            cin >> u >> v;
            --u, --v;
            while (get_min(u) > v) {
                int mn = get_min(u);
                int nr = get_min(p[mn]);
                r[uf.merge(mn, p[mn])] = nr;
            }
        } else {
            int x;
            cin >> x;
            --x;
            cout << get_min(x) + 1 << '\n';
        }
    }
}
